1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type QuoteStep = {
9	  op: "quote";
10	  items: Item[];
11	};
12	
13	export type Scenario = {
14	  customer: { yearsWithMHPCO: number };
15	  steps: QuoteStep[];
16	};
17	
18	export type ScenarioResult = {
19	  results: unknown[];
20	};
21	
22	const PROCESSING_FEE = 5;
23	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
24	
25	const BASE_PREMIUMS: Record<string, number> = {
26	  sword: 100,
27	  amulet: 60,
28	  staff: 80,
29	  potion: 40,
30	  rune: 25,
31	  moonstone: 25,
32	};
33	
34	const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];
35	
36	const BLOCK_SIZE = 3;
37	const BLOCK_BASE_PREMIUM = 60;
38	
39	const alikeItemGroups = (items: Item[]): Item[][] => [
40	  ...items
41	    .reduce(
42	      (groups, item) =>
43	        groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
44	      new Map<string, Item[]>(),
45	    )
46	    .values(),
47	];
48	
49	const basePremiumOfGroup = (group: Item[]): number =>
50	  group.length === BLOCK_SIZE
51	    ? BLOCK_BASE_PREMIUM
52	    : group.reduce((total, item) => total + basePremiumOf(item), 0);
53	
54	const totalBasePremiumOf = (items: Item[]): number =>
55	  alikeItemGroups(items).reduce(
56	    (total, group) => total + basePremiumOfGroup(group),
57	    0,
58	  );
59	
60	const roundedInMHPCOsFavour = (premium: number): number => Math.ceil(premium);
61	
62	type ItemSurchargeRule = {
63	  appliesTo: (item: Item) => boolean;
64	  rate: number;
65	};
66	
67	const CURSE_SURCHARGE_RATE = 0.5;
68	const HIGH_ENCHANTMENT_THRESHOLD = 5;
69	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
70	
71	const ITEM_SURCHARGE_RULES: ItemSurchargeRule[] = [
72	  { appliesTo: (item) => item.cursed === true, rate: CURSE_SURCHARGE_RATE },
73	  {
74	    appliesTo: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
75	    rate: HIGH_ENCHANTMENT_SURCHARGE_RATE,
76	  },
77	];
78	
79	const totalSurchargeRateOf = (item: Item): number =>
80	  ITEM_SURCHARGE_RULES.reduce(
81	    (rate, rule) => (rule.appliesTo(item) ? rate + rule.rate : rate),
82	    0,
83	  );
84	
85	const surchargeOf = (item: Item): number =>
86	  basePremiumOf(item) * totalSurchargeRateOf(item);
87	
88	const totalItemSurchargeOf = (items: Item[]): number =>
89	  items.reduce((total, item) => total + surchargeOf(item), 0);
90	
91	const quotePremium = (items: Item[]): number => {
92	  const basePremium = totalBasePremiumOf(items);
93	  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
94	
95	  return roundedInMHPCOsFavour(
96	    basePremium +
97	      totalItemSurchargeOf(items) +
98	      firstInsuranceSurcharge +
99	      PROCESSING_FEE,
100	  );
101	};
102	
103	export const runScenario = (scenario: Scenario): ScenarioResult => ({
104	  results: scenario.steps.map((step) => ({
105	    premium: quotePremium(step.items),
106	  })),
107	});
