const alikeItemGroups = (items: Item[]): Item[][] => {
  const groupsByType = new Map<string, Item[]>();

  for (const item of items) {
    const group = groupsByType.get(item.type) ?? [];
    group.push(item);
    groupsByType.set(item.type, group);
  }

  return [...groupsByType.values()];
};
